import json, numpy as np, pickle, itertools
from sklearn.linear_model import Ridge, LinearRegression, HuberRegressor
rows=pickle.load(open('rows.pkl','rb'))
pids=np.array([r['pid'] for r in rows]); y=np.array([r['y'] for r in rows])
def lopo(keys, alpha=1.0, model='ridge', transform=None):
    X=np.array([[r[k] for k in keys] for r in rows], dtype=float)
    if transform: X=transform(X)
    errs={}
    for p in np.unique(pids):
        tr=pids!=p; te=pids==p
        mu=X[tr].mean(0); sd=X[tr].std(0)+1e-9
        Xtr=(X[tr]-mu)/sd; Xte=(X[te]-mu)/sd
        if model=='ridge': m=Ridge(alpha=alpha).fit(Xtr,y[tr])
        elif model=='huber': m=HuberRegressor(alpha=alpha, max_iter=1000).fit(Xtr,y[tr])
        pred=m.predict(Xte)
        errs[p]=np.mean(np.abs(pred-y[te]))
    return np.mean(list(errs.values())), errs
# constant
print('const', np.mean([np.mean(np.abs(y[pids==p]-y[pids!=p].mean())) for p in np.unique(pids)]))
